                window,
                threshold,
                tolerance,
                minimum,
            ) = _load_trace_converge_manifest(argv[2])
            report = ppo_trace_converge_many(
                runs,
                window=window,
                threshold=threshold,
                tolerance=tolerance,
                minimum=minimum,
            )
            out = json.dumps(
                report,
                ensure_ascii=True,
                allow_nan=False,
                separators=(",", ":"),
            )
        except (TypeError, ValueError):
            return 2
        sys.stdout.write(out + "\n")
        return 0
    if command == "trace-converge-compare" and len(argv) == 4:
        try:
            out = _trace_converge_compare(argv[2], argv[3])
        except (TypeError, ValueError):
            return 2
        sys.stdout.write(out + "\n")
        return 0
    return 2


